from __future__ import annotations

import uuid
from decimal import Decimal

import pytest
from app.libs.post_trade_allocation.repository import PostTradeAllocationRepository
from app.libs.post_trade_allocation.service import PostTradeAllocationService
from app.models.post_trade_allocation import RunStatus, RunTrigger

from tests.libs.post_trade_allocation.conftest import make_confirmed_period, make_model, make_user


@pytest.fixture
def service(session):
    return PostTradeAllocationService(session)


@pytest.fixture
def repo(session):
    return PostTradeAllocationRepository(session)


def _seed_completed_run(
    session, repo, *, model, user, trade_date, traded, trigger=RunTrigger.MANUAL
):
    # ponytail: post_trade_allocation_runs.period_id is NOT NULL (DB-1/DB-5) —
    # a confirmed period must exist before any run row can be written, same
    # narrow fix authorized for BE-3's own test seeding. Unique label per call
    # since allocation_periods.label is unique and one test may seed >1 run.
    period = make_confirmed_period(session, label=f"P-CONFIRMED-{uuid.uuid4()}")
    run = repo.create_run(
        trade_date=trade_date,
        period_id=period.id,
        status=RunStatus.COMPLETED.value,
        trigger=trigger.value,
        grand_total=Decimal(str(traded)),
        run_by=None,
    )
    repo.write_cells(
        [
            {
                "run_id": run.id,
                "model_id": model.id,
                "user_id": user.id,
                "model_traded": Decimal(str(traded)),
                "units": Decimal("1"),
                "units_total": Decimal("1"),
                "allocated": Decimal(str(traded)),
                "pct": Decimal("100.000"),
                "ib_account": "U-1234567",
                "model_name": model.name,
                "model_acct": "U-1234567",
            }
        ]
    )
    session.commit()
    return run


def _seed_empty_run(session, repo, *, trade_date, trigger=RunTrigger.MANUAL):
    # ponytail: same NOT-NULL period_id fix as _seed_completed_run above.
    period = make_confirmed_period(session, label=f"P-CONFIRMED-{uuid.uuid4()}")
    run = repo.create_run(
        trade_date=trade_date,
        period_id=period.id,
        status=RunStatus.EMPTY.value,
        trigger=trigger.value,
        grand_total=Decimal("0"),
        run_by=None,
    )
    return run


