def test_get_view_returns_none_for_date_with_no_run(service):
    assert service.get_view("20990101") is None


def test_get_view_returns_none_for_date_with_only_empty_run(session, repo, service):
    _seed_empty_run(session, repo, trade_date="20260604")
    session.commit()
    assert service.get_view("20260604") is None


def test_get_view_returns_latest_non_empty_trade_date_when_no_date_given(session, repo, service):
    model = make_model(session)
    user = make_user(session)
    _seed_completed_run(session, repo, model=model, user=user, trade_date="20260601", traded=100)
    _seed_completed_run(session, repo, model=model, user=user, trade_date="20260603", traded=200)

    view = service.get_view()
    assert view.tradeDate == "2026-06-03"


# ponytail (unit A4): D-9 ("late-arriving order for the same tradeDate/model
# creates a second run row, get_view sums across both") is retired --
# trade_date is now UNIQUE on post_trade_allocation_runs, so a second run
# row for a date that already has one can no longer be written. The
# multi-run-per-date seeding this test relied on is impossible now; there is
# nothing left to sum across.


def test_get_view_never_recomputes_from_orders(session, repo, service):
    """The run already froze the split; a stray/contradictory Order row for the
    same tradeDate/model must not change what get_view reports."""
    from tests.libs.post_trade_allocation.conftest import make_order

    model = make_model(session)
    user = make_user(session)
    _seed_completed_run(session, repo, model=model, user=user, trade_date="20260603", traded=100)
    # An unallocated order that would sum to a very different total if get_view
    # (incorrectly) re-aggregated from `orders` instead of reading the frozen cells.
    make_order(session, trade_date="20260603", model=model.name, proceeds=999999)
    session.commit()

    view = service.get_view("20260603")
    assert view.grandTotal == 100.0


def test_get_view_requested_date_with_no_runs_at_all_returns_none(service):
    assert service.get_view("20260603") is None


