def test_list_runs_default_excludes_empty(session, repo, service):
    model = make_model(session)
    user = make_user(session)
    _seed_completed_run(session, repo, model=model, user=user, trade_date="20260603", traded=100)
    _seed_empty_run(session, repo, trade_date="20260604")
    session.commit()

    result = service.list_runs()
    dates = {r.date for r in result.runs}
    assert dates == {"2026-06-03"}


def test_list_runs_include_empty_true_includes_both(session, repo, service):
    model = make_model(session)
    user = make_user(session)
    _seed_completed_run(session, repo, model=model, user=user, trade_date="20260603", traded=100)
    _seed_empty_run(session, repo, trade_date="20260604")
    session.commit()

    result = service.list_runs(include_empty=True)
    dates = {r.date for r in result.runs}
    assert dates == {"2026-06-03", "2026-06-04"}


# ponytail (unit A4): this used to seed two runs on the SAME trade_date to
# prove list_runs collapses them into one entry -- trade_date is UNIQUE now,
# so that seeding is impossible and "one entry per date" is guaranteed by
# the schema itself rather than something this layer needs to prove.
def test_list_runs_one_entry_per_trade_date(session, repo, service):
    model = make_model(session)
    user = make_user(session)
    _seed_completed_run(
        session,
        repo,
        model=model,
        user=user,
        trade_date="20260603",
        traded=100,
        trigger=RunTrigger.MANUAL,
    )
    _seed_completed_run(
        session,
        repo,
        model=model,
        user=user,
        trade_date="20260604",
        traded=50,
        trigger=RunTrigger.SCHEDULED,
    )

    result = service.list_runs()
    assert len(result.runs) == 2
    assert {r.grandTotal for r in result.runs} == {100.0, 50.0}


def test_list_runs_empty_database_returns_empty_list(service):
    result = service.list_runs()
    assert result.runs == []
